// Keep the supplied PNGs as originals; generate the smaller files served to browsers.
import { createHash } from "node:crypto";
import { mkdir, readdir, stat, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import sharp from "sharp";
import { format } from "prettier";

const directory = new URL("../public/themes/", import.meta.url);
await mkdir(new URL("optimized/", directory), { recursive: true });
const assets = {};
const rules = [
  "/* Generated by npm run themes:optimize. Edit the PNG originals, then regenerate. */",
];
let originalBytes = 0,
  optimizedBytes = 0;
for (const file of (await readdir(directory))
  .filter((file) => file.endsWith(".png"))
  .sort()) {
  const name = file.slice(0, -4);
  const image = sharp(fileURLToPath(new URL(file, directory)));
  const full = await image.clone().webp({ quality: 88, effort: 6 }).toBuffer();
  const preview = await image
    .clone()
    .resize({ width: 192 })
    .webp({ quality: 55, effort: 6 })
    .toBuffer();
  const hash = createHash("sha256").update(full).digest("hex").slice(0, 12);
  assets[name] = `/themes/optimized/${name}.${hash}.webp`;
  await writeFile(new URL(`optimized/${name}.${hash}.webp`, directory), full);
  const theme = name.replace(/-(light|dark)$/, "");
  const selector = name.endsWith("-dark")
    ? `[data-mode="dark"] .theme-${theme}`
    : `.theme-${theme}`;
  rules.push(
    `${selector} {\n  --theme-wallpaper: url("${assets[name]}");\n  --theme-preview: url("data:image/webp;base64,${preview.toString("base64")}");\n}`,
  );
  originalBytes += (await stat(new URL(file, directory))).size;
  optimizedBytes += full.length;
}
await writeFile(
  new URL("../lib/theme-assets.ts", import.meta.url),
  await format(
    `// Generated by npm run themes:optimize.\nexport const themeAssets: Record<string, string> = ${JSON.stringify(assets, null, 2)};\n`,
    { parser: "typescript" },
  ),
);
await writeFile(
  new URL("../app/theme-assets.css", import.meta.url),
  rules.join("\n") + "\n",
);
console.log(
  `Theme wallpapers: ${(originalBytes / 1e6).toFixed(1)} MB → ${(optimizedBytes / 1e6).toFixed(1)} MB. Embedded previews need no image requests.`,
);
